import { remapKeys } from "./remap-keys.util.js";
const RUNTIME_METRICS_KEY_MAP = {
    cpu: "c",
    memory: "m",
    gc: "g",
    eventLoop: "e",
};
const CPU_KEY_MAP = {
    user: "u",
    system: "s",
    percentageUsed: "p",
};
const MEMORY_KEY_MAP = {
    rss: "r",
    heapTotal: "ht",
    heapUsed: "hu",
    external: "e",
    arrayBuffers: "ab",
    percentageUsed: "p",
};
const GC_KEY_MAP = {
    count: "c",
    totalDuration: "td",
    breakdown: "b",
};
const GC_BREAKDOWN_KEY_MAP = {
    minor: "m",
    major: "j",
    incremental: "i",
};
const EVENT_LOOP_KEY_MAP = {
    lag: "l",
    utilization: "u",
};
export class RuntimeMetricsEncoder {
    static encode(metrics) {
        const encoded = remapKeys(metrics, RUNTIME_METRICS_KEY_MAP);
        if (metrics.cpu) {
            encoded.c = remapKeys(metrics.cpu, CPU_KEY_MAP);
        }
        if (metrics.memory) {
            encoded.m = remapKeys(metrics.memory, MEMORY_KEY_MAP);
        }
        if (metrics.gc) {
            encoded.g = remapKeys(metrics.gc, GC_KEY_MAP);
            if (metrics.gc.breakdown) {
                encoded.g.b = remapKeys(metrics.gc.breakdown, GC_BREAKDOWN_KEY_MAP);
            }
        }
        if (metrics.eventLoop) {
            encoded.e = remapKeys(metrics.eventLoop, EVENT_LOOP_KEY_MAP);
        }
        return encoded;
    }
}
